/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

System_Type system_type_get (void) 
{
  static System_Type system_type ;

  UInt16 size = 0 ;

  if(nvfs_rd_size(nvfs_sys_type , &size) == NVFS_OK)
    {
      if(size == sizeof(system_type))
        {
		  if (nvfs_rd(nvfs_sys_type , &system_type) == NVFS_OK)
		    {
		  	  #if DBG_SYSTEM_TYPE == 1
			    dbg_tx_text ("\nsystem type successfully loaded") ;
			  #endif
			    return system_type ;	
		    }	  
        }
    }   
  #if DBG_SYSTEM_TYPE == 1
    dbg_tx_text ("\nsystem type nvfs error") ;
  #endif
  return (System_Type)FALSE ;	// error

}
